ALTER TABLE "jobs" ADD COLUMN "inventory_id" bigint NULL, ADD COLUMN "template_id" bigint NULL, ADD COLUMN "template_name" character varying NULL, ADD COLUMN "kind" character varying NULL;
CREATE INDEX "job_template_id" ON "jobs" ("template_id");
CREATE TABLE "templates" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "description" character varying NULL, "kind" character varying NOT NULL, "definition" character varying NOT NULL, "defaults" jsonb NULL, "prompts" jsonb NULL, "required_caps" jsonb NULL, "survey_enabled" boolean NOT NULL DEFAULT false, "allow_simultaneous" boolean NOT NULL DEFAULT false, "inventory_templates" bigint NOT NULL, "organization_templates" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "templates_inventories_templates" FOREIGN KEY ("inventory_templates") REFERENCES "inventories" ("id") ON DELETE NO ACTION, CONSTRAINT "templates_organizations_templates" FOREIGN KEY ("organization_templates") REFERENCES "organizations" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "template_name_organization_templates" ON "templates" ("name", "organization_templates");
CREATE INDEX "template_kind_definition" ON "templates" ("kind", "definition");
CREATE TABLE "saved_launch_configs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NULL, "fields" jsonb NULL, "answers" jsonb NULL, "template_saved_configs" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "saved_launch_configs_templates_saved_configs" FOREIGN KEY ("template_saved_configs") REFERENCES "templates" ("id") ON DELETE CASCADE);
CREATE INDEX "savedlaunchconfig_name_template_saved_configs" ON "saved_launch_configs" ("name", "template_saved_configs");
CREATE TABLE "survey_questions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "variable" character varying NOT NULL, "label" character varying NOT NULL, "help" character varying NULL, "question_type" character varying NOT NULL, "required" boolean NOT NULL DEFAULT false, "default_value" character varying NULL, "choices" jsonb NULL, "min_value" bigint NOT NULL DEFAULT 0, "max_value" bigint NOT NULL DEFAULT 0, "display_order" bigint NOT NULL DEFAULT 0, "template_survey_questions" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "survey_questions_templates_survey_questions" FOREIGN KEY ("template_survey_questions") REFERENCES "templates" ("id") ON DELETE CASCADE);
CREATE INDEX "surveyquestion_display_order_template_survey_questions" ON "survey_questions" ("display_order", "template_survey_questions");
CREATE UNIQUE INDEX "surveyquestion_variable_template_survey_questions" ON "survey_questions" ("variable", "template_survey_questions");
